import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Patch implements Opcodes{
 static final String P="net/flashlight/battery/Power";
 static byte[] integration(byte[]b){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);int changed=0;for(var m:c.methods){String helper=switch(m.name){case "isLamp"->"light";case "lit"->"on";case "swapped"->"swapped";case "toggle"->"toggle";default->null;};if(helper==null)continue;m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;m.instructions.add(new VarInsnNode(ALOAD,0));String result=m.name.equals("swapped")?"Ljava/lang/Object;":m.name.equals("toggle")?"V":"Z";m.instructions.add(new MethodInsnNode(INVOKESTATIC,P,helper,"(Ljava/lang/Object;)"+result,false));if(m.name.equals("swapped"))m.instructions.add(new TypeInsnNode(CHECKCAST,"net/minecraft/world/item/ItemStack"));m.instructions.add(new InsnNode(result.equals("V")?RETURN:result.equals("Z")?IRETURN:ARETURN));changed++;}if(changed!=4)throw new AssertionError("Expected four lamp controls");ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);return w.toByteArray();}
 public static void main(String[]args)throws Exception{Map<String,byte[]>e=new TreeMap<>();try(var z=new ZipFile(args[0])){for(var n:Collections.list(z.entries())){byte[]b=z.getInputStream(n).readAllBytes();if(args[3].equals("integration")&&n.getName().equals("dev/zomboid/integration/Lamps.class"))b=integration(b);e.put(n.getName(),b);}}
 if(!args[3].equals("integration"))try(var fs=Files.walk(Path.of(args[2]))){for(var p:fs.filter(p->p.toString().endsWith(".class")).toList())e.put(Path.of(args[2]).relativize(p).toString(),Files.readAllBytes(p));}
 for(var en:e.entrySet())if(en.getKey().endsWith(".class")){var c=new ClassNode();new ClassReader(en.getValue()).accept(c,0);for(var m:c.methods)if((m.access&(ACC_NATIVE|ACC_ABSTRACT))==0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);}
 try(var z=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var n:e.entrySet()){var ze=new ZipEntry(n.getKey());ze.setTime(0);z.putNextEntry(ze);z.write(n.getValue());z.closeEntry();}}System.out.println("FLASHLIGHT7_INTEGRATION_BYTECODE_VERIFIED "+args[3]);}
}
